__NUXT_JSONP__("/por/school-calendar", {data:[{details:{slug:"por",pageTitle:"Calendário Escolar | Mentor Language Institute",pageDescription:"A data de início do programa varia dependendo dos alunos com visto F1 ou não-F1.",title:"Calendário Escolar",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003EAmarelo\u003C\u002Ffont\u003E: Data de Início do Programa (módulo)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003EVerde\u003C\u002Ffont\u003E: não tem aula (feriado)"],schoolCalendar:{title:"Data de Início do Programa",description:["\u003Cspan class=\"ymarker\"\u003EA data de início do programa varia dependendo dos alunos com visto F1 ou não-F1.\u003C\u002Fspan\u003E"],lists:[{key:"Não tem o visto de Estudante F1",value:["Os alunos que não tem o visto de estudante podem iniciar o programa em qualquer segunda-feira.\u003Cbr\u003E Se a segunda-feira for feriado, a data de início do programa será terça-feira para essa semana."]},{key:"Tem o vistos de Estudante F1",value:["Os alunos com visto de Estudante (F1), apenas podem começar em segundas-feiras específicas (datas em amarelo no Calendário).","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"Perguntas frequentes sobre a data de chegada nos EUA",lists:[{key:"\u003Cb\u003EP: Quantos dias antes da data de início do programa um aluno pode entrar nos EUA?\u003C\u002Fb\u003E",value:["R: A MLI não exige que nossos alunos cheguem nos EUA com um número específico de dias de antecedência. No entanto, nossos alunos geralmente entram nos EUA um ou dois dias antes da data de Início do Programa."],note:"Observação: Os alunos internacionais podem entrar nos EUA 30 dias antes da data de início do programa."},{key:"\u003Cb\u003EP: É possível mudar para a acomodação antes da data de início do programa?\u003C\u002Fb\u003E",value:["R: Sim, nós podemos organizar o seu check-in (a entrada na acomodação) em qualquer data. \u003Cbr \u002F\u003ESe houver mais perguntas, não hesite em nos consultar."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:30.877Z",updatedAt:"2026-04-24T11:47:24.330Z"}}],fetch:{},mutations:void 0});